sys_script_include.script:
var DayOneDelayForecaster = Class.create();
DayOneDelayForecaster.prototype = {
    initialize: function(planSysId) {
        this.planSysId = planSysId;
    },

    evaluateForecast: function() {
        var planGr = new GlideRecord('x_1919740_dayone_0_onboarding_plan');
        if (!planGr.get(this.planSysId)) {
            return 'no_joining_date';
        }

        var joiningDateStr = planGr.getValue('joining_date');
        if (!joiningDateStr) {
            return 'no_joining_date';
        }

        var joiningDate = new GlideDateTime(joiningDateStr);
        var now = new GlideDateTime();
        var daysRemaining = GlideDateTime.subtract(now, joiningDate).getDayPart();

        // Query open/in_progress tasks
        var gr = new GlideRecord('x_1919740_dayone_0_onboarding_task');
        gr.addQuery('plan', this.planSysId);
        var stateQuery = gr.addQuery('task_state', 'open');
        stateQuery.addOrCondition('task_state', 'in_progress');
        gr.query();

        var anyMandatoryDelayed = false;
        var anyTaskDelayed = false;

        while (gr.next()) {
            var estDays = parseInt(gr.getValue('est_remaining_days'), 10) || 0;
            var isMandatory = gr.getValue('mandatory') == '1';

            if (estDays > daysRemaining) {
                if (isMandatory) {
                    anyMandatoryDelayed = true;
                }
                anyTaskDelayed = true;
            }
        }

        // Rule-based forecast
        if (anyMandatoryDelayed) {
            gs.info('DayOneDelayForecaster: Rule-based forecast - delayed (mandatory task exceeds remaining days)');
            return 'delayed';
        }

        if (anyTaskDelayed) {
            gs.info('DayOneDelayForecaster: Rule-based forecast - delay_forecast (task exceeds remaining days)');
            return 'delay_forecast';
        }

        gs.info('DayOneDelayForecaster: Rule-based forecast - on_track');
        return 'on_track';
    },

    type: 'DayOneDelayForecaster'
};
